// Two threads, each trying not to deadlock by backing off politely —

// but the backoff is perfectly symmetric, so they fall into lockstep forever

void politeAcquire(Lock myLock, Lock otherLock) {

    while (true) {
        myLock.lock();
        if (!otherLock.tryLock()) {              // other lock is taken

            myLock.unlock();                       // back off — release what I have, to 
be polite

            continue;                              // and try the whole thing again 
immediately

        }

        try { /* do work with both locks */ return; }
        finally { otherLock.unlock(); myLock.unlock(); }
    }
}
// If both threads run this same logic and their timing stays synchronized,
// each one's "polite" retry collides with the other's, every single time

