// A naive lock implementation that always wakes the most recently waiting
// thread (last-in-first-out) instead of the longest-waiting one — a thread
// that has been waiting a long time can be perpetually overtaken by newcomers

class UnfairLock {

    Deque<Thread> waitQueue = new ArrayDeque<>();

    void lock() {

        waitQueue.addFirst(Thread.currentThread());   // added to the FRONT
        // whoever arrives next also goes to the front and gets served first —
        // the thread at the back can starve indefinitely under steady arrivals
    }
}

// The fix: use a fair lock, which serves threads in arrival order (FIFO)

import java.util.concurrent.locks.ReentrantLock;

ReentrantLock fairLock = new ReentrantLock(true);  // true = fairness enabled

// with fairness on, the longest-waiting thread is always served next

