// A naive lock implementation that always wakes the most recently waiting
// thread (last in first out) instead of the longest waiting one, a thread
// that has been waiting a long time can be perpetually overtaken by newcomers

class UnfairLock {
    std::deque<std::thread::id> waitQueue;

public:
    void lock() {
        waitQueue.push_front(std::this_thread::get_id());   // added to the FRONT
        // whoever arrives next also goes to the front and gets served first,
        // the thread at the back can starve indefinitely under steady arrivals
    }
};

// The fix: hand out tickets and serve them in arrival order (FIFO)

class FairLock {
    std::atomic<unsigned> nextTicket{0};
    std::atomic<unsigned> nowServing{0};

public:
    void lock() {
        const unsigned myTicket = nextTicket.fetch_add(1);
        while (nowServing.load(std::memory_order_acquire) != myTicket) {
            std::this_thread::yield();
        }
    }
    void unlock() { nowServing.fetch_add(1, std::memory_order_release); }
};

// with a ticket lock, the longest waiting thread is always served next

